<div x-data="attendanceRecords({{ Illuminate\Support\Js::from($records) }},{{ Illuminate\Support\Js::from($preFilterEmployeeId) }})" class="space-y-4"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><input x-model.debounce.300ms="search" placeholder="Search employee" aria-label="Search employee" class="rounded border p-2.5"><input type="date" x-model="startDate" aria-label="Start date" class="rounded border p-2.5"><input type="date" x-model="endDate" aria-label="End date" class="rounded border p-2.5"><select x-model="status" class="rounded border p-2.5"><option value="">All statuses</option><option>Present</option><option>Late</option><option>Absent</option><option>Half-Day</option></select></div><p x-show="dateRangeError" class="text-sm text-red-700">End date must be on or after start date.</p>
<x-data-table><thead class="bg-gray-50"><tr>@foreach(['Date','Employee Name','Time In','Time Out','Duration','Status','Method','Actions'] as $h)<th class="p-3">{{ $h }}</th>@endforeach</tr></thead><tbody><template x-for="r in pageRows" :key="r.employee_id+r.work_date"><tr class="border-t"><td class="p-3" x-text="r.work_date"></td><td class="p-3" x-text="r.full_name"></td><td class="p-3" x-text="r.time_in||'—'"></td><td class="p-3" x-text="r.time_out||'—'"></td><td class="p-3" x-text="duration(r)"></td><td class="p-3"><span x-text="r.status" class="rounded-full bg-gray-100 px-2 py-1"></span></td><td class="p-3" x-text="r.method"></td><td class="p-3 whitespace-nowrap"><button class="text-teal-800 underline" @click="selected=r;modal='view'">View</button> <button class="text-teal-800 underline" @click="selected=r;modal='adjust'">Request Adjustment</button></td></tr></template><tr x-show="!filtered.length"><td colspan="8" class="p-8 text-center text-gray-700" x-text="`No records found${search ? ' for “'+search+'”' : ''}.`"></td></tr></tbody></x-data-table><div class="flex justify-between text-sm" x-show="filtered.length>15"><span x-text="`Page ${page} of ${pages}`"></span><div><button @click="page=Math.max(1,page-1)" class="rounded border px-3 py-2">Previous</button> <button @click="page=Math.min(pages,page+1)" class="rounded border px-3 py-2">Next</button></div></div>
<div x-show="modal==='view'" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><div class="w-full max-w-lg rounded-xl bg-white p-6" x-trap.inert.noscroll="modal==='view'||modal==='adjust'" role="dialog" aria-modal="true"><h2 class="text-lg font-semibold">Attendance details</h2><template x-if="selected"><dl class="my-4 grid grid-cols-2 gap-3 text-sm"><dt>Employee</dt><dd x-text="selected.full_name"></dd><dt>Date</dt><dd x-text="selected.work_date"></dd><dt>Time in / out</dt><dd x-text="(selected.time_in||'—')+' / '+(selected.time_out||'—')"></dd><dt>Method</dt><dd x-text="selected.method"></dd><dt>Adjustment notes</dt><dd x-text="selected.adjustment_notes||'None'" class="col-span-2"></dd></dl></template><button @click="modal=''" class="rounded border px-4 py-2">Close</button></div></div>
<div x-show="modal==='adjust'" x-cloak class="fixed inset-0 z-40 grid place-items-center bg-black/50 p-4"><form @submit.prevent="modal='';$dispatch('show-toast',{message:'Adjustment request submitted (demo).'})" class="w-full max-w-lg space-y-3 rounded-xl bg-white p-6" x-trap.inert.noscroll="modal==='view'||modal==='adjust'" role="dialog" aria-modal="true"><h2 class="text-lg font-semibold">Request attendance adjustment</h2><label class="block text-sm">Corrected time in<input type="time" class="mt-1 block w-full rounded border p-2.5"></label><label class="block text-sm">Corrected time out<input type="time" class="mt-1 block w-full rounded border p-2.5"></label><label class="block text-sm">Reason<textarea required maxlength="500" class="mt-1 block w-full rounded border p-2.5"></textarea></label><div class="flex justify-end gap-2"><button type="button" @click="modal=''" class="rounded border px-4 py-2">Cancel</button><button class="rounded bg-[#0b1f33] px-4 py-2 text-white">Submit request</button></div></form></div></div>
<script>function attendanceRecords(rows,id){return {rows,search:'',status:'',startDate:'',endDate:'',dateRangeError:false,employeeId:id||'',page:1,modal:'',selected:null,get filtered(){this.dateRangeError=!!(this.startDate&&this.endDate&&this.endDate<this.startDate);if(this.dateRangeError)return [];let q=this.search.toLowerCase();return this.rows.filter(r=>(!this.employeeId||r.employee_id===this.employeeId)&&(!q||r.full_name.toLowerCase().includes(q))&&(!this.status||r.status===this.status)&&(!this.startDate||r.work_date>=this.startDate)&&(!this.endDate||r.work_date<=this.endDate))},get pages(){return Math.max(1,Math.ceil(this.filtered.length/15))},get pageRows(){return this.filtered.slice((this.page-1)*15,this.page*15)},duration(r){if(!r.time_in||!r.time_out)return '—';let [h,m]=r.time_in.split(':').map(Number),[x,y]=r.time_out.split(':').map(Number);return `${Math.max(0,(x*60+y-h*60-m)/60).toFixed(1)} hrs`}}}</script>
